def totals_by_customer(csv_text):
    totals = {}
    lines = csv_text.strip().splitlines()
    for line in lines[1:]:
        if not line.strip():
            continue
        parts = [p.strip() for p in line.split(",")]
        if len(parts) != 3:
            continue
        try:
            amount = float(parts[2])
